23. func newOAuthServerConfig(cfg config.OAuthServerConfig, refreshTokenTTL time.Duration) *oauthserver.Config {
24. 	result := &oauthserver.Config{
25. 		Issuer:                                cfg.BaseURL,
26. 		ResourceIdentifier:                    cfg.ResourceIdentifier,
27. 		AccessTokenTTL:                        int64(DefaultAccessTokenTTL / time.Second),
28. 		RefreshTokenTTL:                       int64(refreshTokenTTL / time.Second),
