40. 		AllowLocalhostRedirectURIs:            cfg.AllowLocalhostRedirectURIs,
41. 		TrustedAudiences:                      cfg.TrustedAudiences,
42. 	}
43. 	if cfg.EnableJWTMode {
44. 		result.AccessTokenFormat = oauthserver.AccessTokenFormatJWT
45. 	}
46. 	return result
47. }
48. 
49. // buildOAuthServerOptions assembles the functional options for the mcp-oauth server.
50. // instrumentation.New registers a Prometheus collector on the OTel global
51. // provider, so a second call in the same process will race or duplicate-register.
52. func buildOAuthServerOptions(cfg config.OAuthServerConfig, logger *slog.Logger) ([]oauth.ServerOption, error) {
53. 	inst, err := instrumentation.New(instrumentation.Config{
54. 		Enabled:         true,
