58. 	})
59. 	if err != nil {
60. 		return nil, fmt.Errorf("failed to create instrumentation: %w", err)
61. 	}
62. 
63. 	opts := []oauth.ServerOption{
64. 		oauth.WithInstrumentation(inst),
65. 		oauth.WithAuditor(security.NewAuditor(logger, true, security.WithPIIRedaction(true))),
66. 		oauth.WithRateLimiter(security.NewRateLimiter(DefaultIPRateLimit, DefaultIPBurst, logger)),
67. 		oauth.WithUserRateLimiter(security.NewRateLimiter(DefaultUserRateLimit, DefaultUserBurst, logger)),
68. 		oauth.WithSecurityEventRateLimiter(security.NewRateLimiter(DefaultSecurityEventRate, DefaultSecurityEventBurst, logger)),
69. 		oauth.WithClientRegistrationRateLimiter(security.NewClientRegistrationRateLimiterWithConfig(
