76. 	}
77. 
78. 	if len(cfg.KubernetesSATrusts) > 0 {
79. 		trusts := make([]oauthserver.KubernetesSATrust, len(cfg.KubernetesSATrusts))
80. 		for i, t := range cfg.KubernetesSATrusts {
81. 			trusts[i] = oauthserver.KubernetesSATrust{
82. 				Issuer:                 t.Issuer,
83. 				JwksURL:                t.JwksURL,
84. 				AllowedAudiences:       t.AllowedAudiences,
85. 				AllowedScopes:          t.AllowedScopes,
86. 				AllowedNamespaces:      t.AllowedNamespaces,
87. 				AllowedServiceAccounts: t.AllowedServiceAccounts,
88. 			}
89. 		}
90. 		opts = append(opts, oauthserver.WithKubernetesSATrust(trusts))
91. 	}
92. 
93. 	if len(cfg.TrustedIssuers) > 0 {
