117. func parseCIDRs(cidrs []string) ([]*net.IPNet, error) {
118. 	result := make([]*net.IPNet, 0, len(cidrs))
119. 	for _, s := range cidrs {
120. 		_, ipnet, err := net.ParseCIDR(s)
