129. // newDPoPReplayCache returns a DPoP replay cache and, when Valkey storage is
130. // configured, the underlying valkeygo.Client. The caller must call Close() on
131. // the returned client (if non-nil) when the cache is no longer needed.
132. func newDPoPReplayCache(storageCfg config.OAuthStorageConfig) (oauthserver.DPoPReplayCache, valkeygo.Client, error) {
133. 	if storageCfg.Type == storage.BackendValkey && storageCfg.Valkey.URL != "" {
134. 		clientOpts := valkeygo.ClientOption{
135. 			InitAddress: []string{storageCfg.Valkey.URL},
136. 			SelectDB:    storageCfg.Valkey.DB,
137. 		}
138. 		if storageCfg.Valkey.Password != "" {
139. 			clientOpts.Password = storageCfg.Valkey.Password
140. 		}
141. 		if storageCfg.Valkey.TLSEnabled {
142. 			clientOpts.TLSConfig = &tls.Config{MinVersion: tls.VersionTLS12}
143. 		}
144. 		client, err := valkeygo.NewClient(clientOpts)
145. 		if err != nil {
146. 			return nil, nil, fmt.Errorf("failed to create Valkey client for DPoP replay cache: %w", err)
147. 		}
148. 		prefix := storageCfg.Valkey.KeyPrefix
149. 		if prefix == "" {
150. 			prefix = "muster:"
151. 		}
152. 		return dpopvalkey.New(client, prefix+"dpop:"), client, nil
153. 	}
154. 	return oauthserver.NewMemoryDPoPReplayCache(), nil, nil
155. }
