169. // checkAllowedClaims verifies that every claim in allowed is present in raw and
170. // matches its pattern. raw is the unverified JWT payload map.
171. func checkAllowedClaims(allowed map[string]string, raw map[string]any) error {
172. 	for claimName, pattern := range allowed {
173. 		rawVal, present := raw[claimName]
