 func buildTrustedIssuers(cfg config.OAuthServerConfig) ([]oauthserver.TrustedIssuer, error) {
 	issuers := make([]oauthserver.TrustedIssuer, 0, len(cfg.TrustedIssuers)+len(cfg.KubernetesSATrusts))
 	for _, iss := range cfg.TrustedIssuers {
 		issuers = append(issuers, oauthserver.TrustedIssuer{
 			Issuer:           iss.Issuer,
 			JwksURL:          iss.JwksURL,
 			AllowedAudiences: iss.AllowedAudiences,
 			AllowedScopes:    iss.AllowedScopes,
 			AllowedClaims:    iss.AllowedClaims,
 		})
 	}

 	for _, trust := range cfg.KubernetesSATrusts {
 		patterns, restricted, err := kubernetesSAAllowedClaimPatterns(trust)
 		if err != nil {
 			return nil, err
 		}
 		base := oauthserver.TrustedIssuer{
 			Issuer:             trust.Issuer,
 			JwksURL:            trust.JwksURL,
 			AllowedAudiences:   trust.AllowedAudiences,
 			AllowedScopes:      trust.AllowedScopes,
 			AllowPrivateIPJWKS: true,
 		}
 		if !restricted {
 			issuers = append(issuers, base)
 			continue
 		}
 		if len(patterns) == 0 {
 			return nil, fmt.Errorf("kubernetes service account trust for issuer %q has no service accounts matching allowed namespaces", trust.Issuer)
 		}
 		for _, pattern := range patterns {
 			issuer := base
 			issuer.AllowedClaims = map[string]string{"sub": pattern}
 			issuers = append(issuers, issuer)
 		}
 	}

 	return issuers, nil
 }

 func kubernetesSAAllowedClaimPatterns(trust config.K8sSATrustConfig) ([]string, bool, error) {
 	allowedNamespaces := make(map[string]struct{}, len(trust.AllowedNamespaces))
 	for _, namespace := range trust.AllowedNamespaces {
 		allowedNamespaces[namespace] = struct{}{}
 	}

 	if len(trust.AllowedServiceAccounts) > 0 {
 		patterns := make([]string, 0, len(trust.AllowedServiceAccounts))
 		for _, serviceAccount := range trust.AllowedServiceAccounts {
 			namespace, name, ok := strings.Cut(serviceAccount, "/")
 			if !ok || namespace == "" || name == "" {
 				return nil, true, fmt.Errorf("invalid Kubernetes service account %q: expected namespace/name", serviceAccount)
 			}
 			if len(allowedNamespaces) > 0 {
 				if _, ok := allowedNamespaces[namespace]; !ok {
 					continue
 				}
 			}
 			patterns = append(patterns, "system:serviceaccount:"+namespace+":"+name)
 		}
 		return patterns, true, nil
 	}

 	patterns := make([]string, 0, len(trust.AllowedNamespaces))
 	for _, namespace := range trust.AllowedNamespaces {
 		patterns = append(patterns, "system:serviceaccount:"+namespace+":*")
 	}
 	return patterns, len(patterns) > 0, nil
 }

